+	Minute = Duration(time.Minute)
+	Day    = Duration(time.Hour * 24)
+)
+
+// Default is the default configuration for a bacalhau node.
+var Default = Bacalhau{
+	DataDir: DefaultDataDir(),
+	API: API{
+		Host: "0.0.0.0",
+		Port: 1234,
