+
+		if field.Type.Kind() == reflect.Struct {
+			// Recursively process nested structs
+			processStructFields(field.Type, newPrefix, file, handleLeafNode)
+		} else {
+			// Handle leaf node
+			handleLeafNode(field, newPrefix)
+		}
